#!/usr/bin/env python3
# REPR COPY (ab3/repr/make_frozen.py): ab3/frozen/harness.py with three edits so that the tokenizer mode and
# the positional variant come from pretrain.pt (see REPR_MANIFEST.json for the diff). Nothing else differs.
"""FROZEN experiment harness for the RL hill-climb, run 3 ("ab3": compute-metered budget). Agents do not edit this file (SPEC.md).

    python frozen/harness.py --out runs/<name> [--seed 0] [--flops F] [--budget 3600] [--rl rl.py] [--gpu auto|N|env]
                             [--gpus 0,1,2,3,4] [--gpu-wait 14400] [--no-score] [--smoke]

One experiment:
  0. --gpu auto (default): take an exclusive GPU lock with frozen/gpulock.py (first free GPU of --gpus,
     waiting up to --gpu-wait s), export CUDA_VISIBLE_DEVICES=<that GPU> for this process and the scoring
     subprocesses, release it at exit (try/finally + atexit + SIGTERM/SIGHUP; the lock holder also frees
     it by itself if this process is SIGKILLed). --gpu N locks GPU N; --gpu env uses CUDA_VISIBLE_DEVICES
     as it is and takes no lock (monitor / tests only).
  1. seed torch/python; load frozen/pretrain.pt into GPT(vocab, 4, 256, 8) with the 'abs' tokenizer;
     copy rl.py to runs/<name>/source/; hash rl.py, harness.py, score.py, metrics.py, gpulock.py, lib/,
     data/, pretrain.pt
  2. model = rl.run(model, tok, targets, budget_secs, device, seed, log, metrics, paths) under the compute
     meter (frozen/meter.py), installed before rl.py is imported: paths['budget'] is the Meter (limit = --flops,
     default DEFAULT_FLOPS). The meter charges every nn.Linear call (x3 with autograd) and CUDA-graph replays;
     torch.compile / torch.jit.script / torch.jit.trace are disabled.
     BudgetExhausted escaping rl.run -> the model object passed in is scored as it stands (budget_exhausted).
     budget_secs is only a wall-clock safety cap (--budget, default 3600): SIGALRM at budget+45 -> "timeout";
     returning after budget+15 is also a timeout. The score depends on the compute, not on the card.
  3. save final.pt (lib.model.save_ckpt layout + stage/seed/shas); greedy held-out damage check
  4. unless --no-score: frozen/score.py --ckpt final.pt --set dev --k 32 --seed 0 (dev, L8-11), then
     --set frontier --k 64 (L12-14); subprocesses on the same GPU
  5. write runs/<name>/summary.json: metric (= dev total), by_len, frontier (total), frontier_by_len, pass1 /
     pass1_by_len / pass4 / pass4_by_len (dev) and frontier_pass1 / ... (frontier), compute, budget_exhausted, ...

Env: AB_SCORE_STUB=1 makes the harness call score.py with --local-stub (plumbing tests only; no daemon).
     AB_ARM overrides the arm name (default: basename of the directory that contains frozen/).
     AB_WORKER (worker name) is stored in the GPU lock and in summary.json.
"""
import argparse, atexit, collections, datetime, hashlib, importlib.util, json, os, random, shutil, signal, subprocess, sys, time, traceback

FROZEN = os.path.dirname(os.path.abspath(__file__))
LIB = os.path.join(FROZEN, 'lib')
DATA = os.path.join(FROZEN, 'data')
for _p in (FROZEN, LIB):
    if _p not in sys.path:
        sys.path.insert(0, _p)
# `import harness` from rl.py must return this module, not a second copy
sys.modules.setdefault('harness', sys.modules[__name__])

import gpulock  # noqa: E402  (stdlib only; must not initialise CUDA)
import torch  # noqa: E402
from model import GPT, variant_kwargs  # noqa: E402  (repr/lib: GPT with positional variants)
from tokenizer import Tokenizer  # noqa: E402
from sample import generate  # noqa: E402
from nd_verify import verify_text  # noqa: E402
from metrics import Metrics  # noqa: E402
import meter as meter_mod  # noqa: E402

# ---- data file names (frozen/data/). The pools for run 2; change only here.
TARGETS_FILE = 'targets_L6-11.jsonl'     # RL pool (no proofs)
TRAIN_CAP6_FILE = 'train_cap6.jsonl'     # cap-6 supervised records (retention)
HELDOUT_CAP6_FILE = 'heldout_cap6.jsonl' # cap-6 records for the in-distribution damage check only
SCORE_SETS = ('dev', 'frontier')         # scored after every run, in this order; dev is `metric`

N_LAYER, D_MODEL, N_HEAD = 4, 256, 8
TIMEOUT_GRACE = 15          # returning later than budget + this is a timeout
ALARM_GRACE = 45            # SIGALRM at budget + this
HELDOUT_N, HELDOUT_STRIDE = 1000, 5   # heldout_cap6.jsonl is length-ordered (1,000 each of 2..6 lines): every 5th record
GREEDY_BATCH, GREEDY_MAX_NEW = 384, 512
SCORE_K = {'dev': 32, 'frontier': 64}   # official k per scored set
SCORE_SEED = 0
DEFAULT_BUDGET = 3600       # wall-clock safety cap only (run 3)
# Compute budget (metered FLOPs, frozen/meter.py). Calibration 2026-09-24 (ab3/calib/runs/cal_graph): run 2's
# n092 recipe (CUDA-graph line-verified sampler), unlimited compute, 1,200 s wall clock on GPU 0 (RTX 3090), seed
# 101: 23 rounds (22 full + one at 0.87) for 2.9989e15 FLOPs = 1.3039e14 per round (sampling 2.07e13, fine-tune
# 1.10e14). 30 rounds (what n092 ran in run 2's same-card replicate) = 3.9117e15 -> 3.9e15 at 2 significant figures.
DEFAULT_FLOPS = 3.9e15      # None / --flops 0 = unmetered (calibration only)
SMOKE_FLOPS = 1e12          # --smoke: about 2.3 seed smoke rounds (4.2-4.5e11 each, mostly its 5 fine-tune steps)
DEFAULT_GPUS = '0,1,2,3,4'
DEFAULT_GPU_WAIT = 4 * 3600
SCORE_TIMEOUT = 60 * 60     # per scoring subprocess (queueing at the daemon included)
SMOKE_TARGETS, SMOKE_BUDGET, SMOKE_HELDOUT = 8, 60, 64
SUMS_FILE = 'SHA256SUMS'

_SHAS = {}      # filled by main(); stored in every checkpoint saved through save_checkpoint
_RUN = {}       # stage/seed for save_checkpoint


class Timeout(BaseException):   # BaseException: a bare `except Exception` in rl.py cannot swallow it
    pass


def log(msg):
    print(f'[{time.strftime("%H:%M:%S")}] {msg}', flush=True)


def read_jsonl(fn):
    with open(fn) as f:
        return [json.loads(l) for l in f if l.strip()]


def file_sha256(fn):
    h = hashlib.sha256()
    with open(fn, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()


def data_shas():
    """SHA-256 of every file under data/, cached in data/SHA256SUMS (sha256sum format) when present.
    The cache is ignored if its file list does not match data/ or any data file (or symlink) was
    created or changed after SHA256SUMS was written (ctime, which `cp -p` cannot backdate)."""
    files = sorted(f for f in os.listdir(DATA) if f != SUMS_FILE and os.path.isfile(os.path.join(DATA, f)))
    sums_path = os.path.join(DATA, SUMS_FILE)
    fresh = os.path.exists(sums_path) and all(
        max(os.lstat(os.path.join(DATA, f)).st_ctime, os.stat(os.path.join(DATA, f)).st_ctime)
        <= os.stat(sums_path).st_mtime for f in files)
    if os.path.exists(sums_path) and not fresh:
        log(f'{SUMS_FILE} is older than a data file; recomputing')
    if fresh:
        cached, sizes = {}, {}
        for l in open(sums_path):
            parts = l.split()
            if len(parts) >= 2:
                cached[parts[-1].lstrip('*')] = parts[0]
        if sorted(cached) == files:
            return {f'data/{f}': cached[f] for f in files}
        log(f'{SUMS_FILE} does not match data/ contents; recomputing')
    out = {f: file_sha256(os.path.join(DATA, f)) for f in files}
    try:
        with open(sums_path, 'w') as fh:
            fh.writelines(f'{h}  {f}\n' for f, h in out.items())
    except OSError as e:
        log(f'could not write {sums_path}: {e}')
    return {f'data/{f}': h for f, h in out.items()}


def all_shas(rl_path):
    shas = {'rl.py': file_sha256(rl_path)}
    for f in ('harness.py', 'meter.py', 'score.py', 'metrics.py', 'gpulock.py', 'pretrain.pt'):
        shas[f] = file_sha256(os.path.join(FROZEN, f))
    for d, _, fs in os.walk(LIB):
        if '__pycache__' in d:
            continue
        for f in sorted(fs):
            if f.endswith('.pyc'):
                continue
            p = os.path.join(d, f)
            shas[os.path.relpath(p, FROZEN)] = file_sha256(p)
    shas.update(data_shas())
    return dict(sorted(shas.items()))


def arm_root():
    d = os.getcwd()
    while True:
        if os.path.isdir(os.path.join(d, 'frozen')):
            return d
        if os.path.dirname(d) == d:
            return os.getcwd()
        d = os.path.dirname(d)


def save_checkpoint(model, tok, path, stage=None, extra=None):
    """Atomic weight snapshot in lib.model.save_ckpt's layout ({'cfg','state','tok_mode','extra'})
    plus 'stage', 'seed', 'shas'; readable by lib.model.load_ckpt. For rl.py's intermediate checkpoints."""
    path = str(path)
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    if stage is None:
        stage = os.path.splitext(os.path.basename(path))[0]
    obj = {'cfg': dict(model.cfg), 'state': {k: v.detach().cpu() for k, v in model.state_dict().items()},
           'tok_mode': tok.mode, 'extra': dict(extra or {}), 'stage': stage, 'seed': _RUN.get('seed'), 'shas': dict(_SHAS)}
    tmp = path + '.tmp'
    torch.save(obj, tmp)
    os.replace(tmp, path)
    return path


def heldout_slice(n=HELDOUT_N):
    recs = read_jsonl(os.path.join(DATA, HELDOUT_CAP6_FILE))
    return recs[::HELDOUT_STRIDE][:n]


def heldout_greedy(model, tok, n=HELDOUT_N, recs=None):
    """Fraction of the fixed held-out cap-6 slice solved by greedy decoding (in-distribution damage check)."""
    recs = recs if recs is not None else heldout_slice(n)
    was_training = model.training
    model.eval()
    outs = generate(model, tok, [r['prompt'] for r in recs], greedy=True, max_new=GREEDY_MAX_NEW, batch=GREEDY_BATCH)
    if was_training:
        model.train()
    ok = sum(verify_text(r['prompt'] + ' ' + p)[0] for r, p in zip(recs, outs))
    return ok / max(len(recs), 1)


VARIANT = {}    # repr: the checkpoint's tokenizer mode and positional variant (lib/model.py), set by load_pretrained


def load_pretrained(device):
    # repr edit: tokenizer mode and model variant from the checkpoint (frozen: Tokenizer('abs'), plain GPT)
    ck = torch.load(os.path.join(FROZEN, 'pretrain.pt'), map_location='cpu')
    tok = Tokenizer(ck.get('tok_mode') or 'abs')
    VARIANT.update(tok_mode=tok.mode, model=variant_kwargs(ck.get('cfg')))
    model = GPT(tok.vocab_size, N_LAYER, D_MODEL, N_HEAD, **VARIANT['model'])
    bad = {k: v for k, v in (ck.get('cfg') or {}).items() if model.cfg.get(k) != v}
    assert not bad, f'pretrain.pt cfg does not match the model built from it: {bad}'
    model.load_state_dict(ck['state'])
    return model.to(device), tok


def import_rl(path):
    spec = importlib.util.spec_from_file_location('rl', path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules['rl'] = mod
    spec.loader.exec_module(mod)
    return mod


def run_score(a, ckpt, which):
    """One scoring subprocess (frozen/score.py client) for set `which`; returns (score dict, secs, line)."""
    cmd = [sys.executable, os.path.join(FROZEN, 'score.py'), '--ckpt', ckpt, '--set', which, '--k', str(SCORE_K[which]),
           '--seed', str(SCORE_SEED), '--tag', f'harness:{a.run_name}']
    if a.smoke:
        cmd.append('--smoke')
    if os.environ.get('AB_SCORE_STUB') == '1':
        cmd.append('--local-stub')
    log('scoring: ' + ' '.join(cmd))
    t0 = time.time()
    p = subprocess.run(cmd, env=os.environ.copy(), capture_output=True, text=True, timeout=SCORE_TIMEOUT)
    secs = time.time() - t0
    sys.stdout.write(p.stdout)
    sys.stderr.write(p.stderr)
    if p.returncode != 0:
        raise RuntimeError(f'score.py --set {which} exited {p.returncode}: {(p.stderr or p.stdout).strip()[-1000:]}')
    fn = 'score.json' if which == 'dev' else f'score_{which}.json'
    with open(os.path.join(os.path.dirname(ckpt), fn)) as f:
        return json.load(f), secs, p.stdout.strip().splitlines()[-1] if p.stdout.strip() else ''


class GpuLease:
    """--gpu auto / N: an exclusive gpulock lease, exported as CUDA_VISIBLE_DEVICES; released exactly once."""

    def __init__(self):
        self.gpu = self.holder = None

    def take(self, a):
        if a.gpu == 'env':
            return None
        gpus = gpulock.parse_gpus(a.gpus) if a.gpu == 'auto' else [int(a.gpu)]
        t0 = time.time()
        gpu, holder = gpulock.acquire(gpus, wait=a.gpu_wait, run=a.run_name, owner=os.getpid(), log=log)
        if gpu is None:
            raise SystemExit(f'harness: no free GPU among {gpus} after {a.gpu_wait:.0f}s (see `gpulock.py status`)')
        self.gpu, self.holder = gpu, holder
        atexit.register(self.drop)
        os.environ['CUDA_VISIBLE_DEVICES'] = str(gpu)
        log(f'gpulock: holding GPU {gpu} (holder pid {holder}) after {time.time() - t0:.0f}s')
        return time.time() - t0

    def drop(self):
        if self.gpu is None:
            return
        gpu, self.gpu = self.gpu, None
        ok = gpulock.release(gpu, self.holder)
        log(f'gpulock: released GPU {gpu}' + ('' if ok else ' (lock still busy?)'))


def _term(signum, frame):   # SIGTERM / SIGHUP -> SystemExit, so finally blocks and atexit run
    raise SystemExit(128 + signum)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', required=True)
    ap.add_argument('--seed', type=int, default=0)
    ap.add_argument('--budget', type=float, default=DEFAULT_BUDGET, help='rl.run wall-clock safety cap, seconds (default 3600)')
    ap.add_argument('--flops', type=float, default=None, help='compute budget in metered FLOPs (default DEFAULT_FLOPS; 0 = unlimited, calibration only)')
    ap.add_argument('--rl', default='rl.py')
    ap.add_argument('--gpu', default='auto', help="auto (lock the first free of --gpus), N (lock GPU N), or env "
                                                  "(use CUDA_VISIBLE_DEVICES as is, no lock)")
    ap.add_argument('--gpus', default=DEFAULT_GPUS, help='GPUs --gpu auto may take (default 0,1,2,3,4)')
    ap.add_argument('--gpu-wait', type=float, default=DEFAULT_GPU_WAIT, help='max seconds to wait for a free GPU')
    ap.add_argument('--no-score', action='store_true')
    ap.add_argument('--smoke', action='store_true', help='8 targets, SMOKE_FLOPS compute, 60 s wall cap, 16-theorem score subsets')
    a = ap.parse_args()
    if a.gpu not in ('auto', 'env') and not a.gpu.isdigit():
        ap.error('--gpu must be auto, env or a GPU index')
    signal.signal(signal.SIGTERM, _term)
    signal.signal(signal.SIGHUP, _term)
    if a.smoke:
        a.budget = SMOKE_BUDGET
        a.flops = SMOKE_FLOPS
    if a.flops is None:
        a.flops = DEFAULT_FLOPS or 0
    out = os.path.abspath(a.out)
    a.run_name = os.path.basename(out.rstrip('/'))
    lease = GpuLease()
    try:
        gpu_wait = lease.take(a)
        return run_experiment(a, out, gpu_wait)
    finally:
        lease.drop()


def run_experiment(a, out, gpu_wait):
    T0 = time.time()
    started = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    os.makedirs(os.path.join(out, 'source'), exist_ok=True)
    rl_path = os.path.abspath(a.rl)
    shutil.copy2(rl_path, os.path.join(out, 'source', 'rl.py'))
    arm = os.environ.get('AB_ARM') or os.path.basename(arm_root())

    random.seed(a.seed)
    torch.manual_seed(a.seed)
    device = 'cuda'
    _RUN['seed'] = a.seed
    _SHAS.update(all_shas(rl_path))
    gpu = f"{os.environ.get('CUDA_VISIBLE_DEVICES', '')}:{torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'cpu'}"
    summary = {'status': None, 'metric': None, 'by_len': None, 'frontier': None, 'frontier_by_len': None,
               'rl_secs': None, 'score_secs': None, 'heldout_greedy': None,
               'rl_stats': {}, 'shas': _SHAS, 'seed': a.seed, 'budget': a.budget, 'gpu': gpu, 'gpu_lock': a.gpu,
               'gpu_wait_secs': gpu_wait, 'worker': os.environ.get('AB_WORKER'), 'started_utc': started,
               'run_name': a.run_name, 'arm': arm, 'smoke': a.smoke, 'out': out, 'targets_file': TARGETS_FILE,
               'flops_budget': a.flops or None, 'compute': None, 'budget_exhausted': False}

    def write_summary(status, **kw):
        summary.update(kw)
        summary['status'] = status
        summary['total_secs'] = time.time() - T0
        tmp = os.path.join(out, 'summary.json.tmp')
        with open(tmp, 'w') as f:
            json.dump(summary, f, indent=1)
        os.replace(tmp, os.path.join(out, 'summary.json'))

    metrics = Metrics(out, a.run_name, arm, t0=T0)
    model, tok = load_pretrained(device)
    targets = read_jsonl(os.path.join(DATA, TARGETS_FILE))
    dup = [n for n, c in collections.Counter(t.get('name') for t in targets).items() if c > 1]
    if dup:   # rl.py keys everything by name; fail before any training
        raise SystemExit(f'harness: {TARGETS_FILE} has {len(dup)} duplicate `name` values (e.g. {dup[:5]}); '
                         f'every target needs a unique name')
    if a.smoke:
        targets = random.Random(a.seed).sample(targets, SMOKE_TARGETS)
    paths = {'targets': os.path.join(DATA, TARGETS_FILE),
             'train_cap6': os.path.join(DATA, TRAIN_CAP6_FILE),
             'heldout_cap6': os.path.join(DATA, HELDOUT_CAP6_FILE),
             'out_dir': out, 'save_checkpoint': save_checkpoint, 'heldout_greedy': heldout_greedy, 'smoke': a.smoke}
    meter = meter_mod.Meter(a.flops or None)
    paths['budget'] = meter
    log(f'run {arm}/{a.run_name}: seed {a.seed}, compute {a.flops or float("inf"):.4g} FLOPs, wall cap {a.budget:.0f}s, gpu {gpu}, {len(targets)} targets '
        f'({TARGETS_FILE}), rl.py {_SHAS["rl.py"][:12]}, harness {_SHAS["harness.py"][:12]}')

    def on_alarm(signum, frame):
        raise Timeout()
    signal.signal(signal.SIGALRM, on_alarm)

    status = 'crash'
    try:
        signal.alarm(int(a.budget + ALARM_GRACE))
        t_rl = time.time()
        policy = model
        meter.install()     # before the import, so rl.py's import-time code is metered (and on the wall clock) too
        try:
            try:
                rl = import_rl(rl_path)
                model = rl.run(model, tok, targets, a.budget, device, a.seed, log, metrics, paths)
            except meter_mod.BudgetExhausted as e:
                log(f'{e}: scoring the policy object as it stands (budget_exhausted)')
                model = policy
                summary['budget_exhausted'] = True
        finally:
            meter.uninstall()
            rl_secs = time.time() - t_rl
            signal.alarm(0)
            summary['rl_secs'] = rl_secs
            summary['compute'] = meter.snapshot()
        log(f"compute used {meter.used():.4e} FLOPs ({meter.frac():.1%} of budget), {meter.opt_steps} optimizer steps")
        summary['rl_stats'] = dict(metrics.summary)
        log(f'rl.run returned after {rl_secs:.1f}s (budget {a.budget:.0f}s)')
        if rl_secs > a.budget + TIMEOUT_GRACE:
            write_summary('timeout', reason=f'rl.run returned after {rl_secs:.1f}s > budget + {TIMEOUT_GRACE}s')
            log('SUMMARY status=timeout')
            return 1
        if not isinstance(model, GPT) or dict(model.cfg) != dict(GPT(tok.vocab_size, N_LAYER, D_MODEL, N_HEAD, **VARIANT['model']).cfg):
            raise TypeError(f'rl.run must return the GPT({tok.vocab_size}, {N_LAYER}, {D_MODEL}, {N_HEAD}) model, got {type(model)}')
        model.eval()
        final = save_checkpoint(model, tok, os.path.join(out, 'final.pt'), stage='final')
        th = time.time()
        hg = heldout_greedy(model, tok, recs=heldout_slice(SMOKE_HELDOUT if a.smoke else HELDOUT_N))
        metrics.log(phase='eval', heldout_greedy=hg, source='harness', secs=time.time() - th)
        summary['heldout_greedy'] = hg
        log(f'held-out greedy (final) {hg:.3f} in {time.time() - th:.0f}s')
        if a.no_score:
            write_summary('ok', scored=False)
            log(f'SUMMARY status=ok (not scored) heldout_greedy={hg:.3f}')
            return 0
        write_summary('scoring')   # provisional: lets score.py log the hashes
        del model
        torch.cuda.empty_cache()
        res = {}
        for which in SCORE_SETS:
            res[which] = run_score(a, final, which)
        dev, dev_secs, dev_line = res['dev']
        fr, fr_secs, fr_line = res['frontier']
        write_summary('ok', scored=True, metric=dev.get('solved'), by_len=dev.get('by_len'),
                      frontier=fr.get('solved'), frontier_by_len=fr.get('by_len'),
                      **{f'{pre}{m}{suf}': sc.get(f'{m}{suf}') for pre, sc in (('', dev), ('frontier_', fr))
                         for m in ('pass1', 'pass4') for suf in ('', '_by_len')},
                      score_secs=dev_secs + fr_secs, dev_score_secs=dev_secs, frontier_score_secs=fr_secs,
                      score=dev, frontier_score=fr, score_line=dev_line, frontier_line=fr_line)
        log(f'SUMMARY status=ok metric={dev.get("solved")} by_len={dev.get("by_len")} '
            f'frontier={fr.get("solved")} frontier_by_len={fr.get("by_len")} '
            f'pass1={dev.get("pass1")} pass4={dev.get("pass4")} frontier_pass1={fr.get("pass1")} frontier_pass4={fr.get("pass4")}')
        return 0
    except Timeout:
        meter.uninstall()
        write_summary('timeout', reason=f'SIGALRM at budget + {ALARM_GRACE}s', rl_stats=dict(metrics.summary), compute=meter.snapshot())
        log('SUMMARY status=timeout (SIGALRM)')
        return 1
    except Exception:
        tb = traceback.format_exc()
        traceback.print_exc()
        write_summary(status, reason=tb[-4000:], rl_stats=dict(metrics.summary))
        log('SUMMARY status=crash')
        return 1
    except SystemExit as e:   # SIGTERM / SIGHUP from outside: record it, then let the lease be released
        write_summary('crash', reason=f'terminated by signal (exit {e.code})', rl_stats=dict(metrics.summary))
        log('SUMMARY status=crash (terminated)')
        raise


if __name__ == '__main__':
    sys.exit(main())
